Kembalikan jawaban langsung (non-streaming, model auto) fetch('https://puruboy-api.vercel.app/api/chat/completions', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({         model: 'auto',         messages: [{ role: 'user', content: 'Halo, apa itu Next.js?' }],         debug: false     }) }).then(res => res.json()).then(console.log);

Streaming SSE fetch('https://puruboy-api.vercel.app/api/chat/completions', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({         model: 'auto',         stream: true,         messages: [             { role: 'system', content: 'Jawab singkat.' },             { role: 'user', content: 'Jelaskan fotosintesis' }         ]     }) }).then(res => {     const reader = res.body.getReader();     const dec = new TextDecoder();     (async () => {         while (true) {             const { done, value } = await reader.read();             if (done) break;             console.log(dec.decode(value));         }     })(); });

